function savingsGraph(group){
 const rows=group.rows||[];if(!rows.length)return '';
 const W=620,H=250,L=72,R=25,T=20,B=40,area=W-L-R;
 const min=Math.min(0,...rows.map(r=>r.balance)),max=Math.max(10000,...rows.map(r=>r.balance));
 const span=max-min,x=i=>L+(rows.length===1?area/2:i*area/(rows.length-1)),y=v=>T+(max-v)/span*(H-T-B);
 const points=rows.map((r,i)=>`${x(i)},${y(r.balance)}`).join(' '),step=Math.max(1,Math.ceil(rows.length/8));
 return `<div class="saving-chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(group.name)}の取り分け残高。毎年の取り分けを足し、購入時に減らしたメモ">${[max,0,...(min<0?[min]:[])].map(v=>`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="${v===0?'#79949e':'#dce9ed'}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${esc(short(v))}</text>`).join('')}<polyline points="${points}" fill="none" stroke="#167e78" stroke-width="3" vector-effect="non-scaling-stroke"/>${rows.map((r,i)=>`${r.purchase?`<circle cx="${x(i)}" cy="${y(r.balance)}" r="5" fill="#c64d39"><title>${r.year}年の購入 ${yen(r.purchase)}・取り分け ${yen(r.setAside)}・残高 ${yen(r.balance)}</title></circle>`:''}${(i===0||i===rows.length-1||i%step===0)?`<text x="${x(i)}" y="${H-10}" text-anchor="middle">${r.year}</text>`:''}`).join('')}</svg><p class="hint">緑の線：取り分け額を加え、購入額を引いたメモ残高　●：購入年。0円未満は積立不足です。</p></div>`
}
