function chartMarkup(rows,label){
 if(!rows.length)return '';
 const mobile=window.matchMedia('(max-width:700px)').matches,W=mobile?440:980,H=mobile?300:360,L=mobile?55:94,R=mobile?55:90,T=mobile?23:25,B=mobile?42:48,plot=H-T-B,barArea=W-L-R,zeroY=T+plot*.72;
 const domain=values=>{const positive=Math.max(10000,...values.map(v=>Math.max(0,v))),negative=Math.max(0,...values.map(v=>Math.max(0,-v))),span=Math.max(positive/.72,negative/.28,10000);return {max:span*.72,min:-span*.28}};
 const asset=domain(rows.flatMap(r=>[r.freeCash??r.cash,r.purposeReserveTotal||0,r.invest,r.assets])),net=domain(rows.map(r=>r.net));
 const y=(v,d)=>T+(d.max-v)/(d.max-d.min)*plot,x=i=>L+(i+.5)*barArea/rows.length,w=Math.max(5,Math.min(28,barArea/rows.length*.68)),step=Math.max(1,Math.ceil(rows.length/8));
 const ticks=[asset.max,asset.max/2,0,asset.min/2,asset.min].map((value,i)=>{const yy=y(value,asset),right=[net.max,net.max/2,0,net.min/2,net.min][i],zero=i===2;return `<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="${zero?'#566f79':'#e1eaee'}" stroke-width="${zero?2:1}"/><text x="${L-7}" y="${yy+4}" text-anchor="end" font-size="12" fill="#526d7a">${esc(zero?'0円':short(value))}</text><text x="${W-R+7}" y="${yy+4}" font-size="12" fill="#a45d26">${esc(zero?'0円':short(right))}</text>`}).join('');
 const bars=rows.map((r,i)=>{const xx=x(i),free=Math.max(0,r.freeCash??r.cash),reserved=Math.max(0,r.purposeReserveTotal||0),invest=Math.max(0,r.invest),freeTop=y(free,asset),reserveTop=y(free+reserved,asset),totalTop=y(free+reserved+invest,asset),negative=(r.freeCash??r.cash)<0?`<rect x="${xx-w/2}" y="${zeroY}" width="${w}" height="${y(r.freeCash??r.cash,asset)-zeroY}" fill="#c33b32"/>`:'';return `<rect x="${xx-w/2}" y="${freeTop}" width="${w}" height="${zeroY-freeTop}" fill="#199981"/><rect x="${xx-w/2}" y="${reserveTop}" width="${w}" height="${freeTop-reserveTop}" fill="#9b6bc3"/><rect x="${xx-w/2}" y="${totalTop}" width="${w}" height="${reserveTop-totalTop}" fill="#3682bd"/>${negative}${r.assets<0?`<circle cx="${xx}" cy="${y(r.assets,asset)}" r="4" fill="#812f3b"/>`:''}`}).join('');
 const line=rows.map((r,i)=>`${x(i)},${y(r.net,net)}`).join(' ');
 return `<div class="chart-wrap" data-chart="${label}"><div class="chart-legend" aria-label="グラフの見方"><span><svg viewBox="0 0 38 25" aria-hidden="true"><rect x="4" y="10" width="11" height="12" fill="#199981"/><rect x="4" y="3" width="11" height="7" fill="#3682bd"/><rect x="23" y="15" width="11" height="7" fill="#199981"/><rect x="23" y="6" width="11" height="9" fill="#3682bd"/></svg><b>積み上げ棒</b> 自由な現金（緑）＋用途別積立（紫）＋投資（青）</span><span><svg viewBox="0 0 38 25" aria-hidden="true"><polyline points="2,20 12,12 21,16 35,4" fill="none" stroke="#dc8139" stroke-width="3"/><circle cx="35" cy="4" r="2" fill="#dc8139"/></svg><b>折れ線</b> その年の収入－支出（年間収支・右軸）</span><span><svg viewBox="0 0 38 25" aria-hidden="true"><line x1="2" x2="36" y1="8" y2="8" stroke="#566f79"/><rect x="14" y="8" width="10" height="14" fill="#c33b32"/></svg><b>赤い棒</b> 0円未満の現金</span></div><div class="chart-scroll"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${label}。左右の0円は同じ高さ。自由な現金・用途別積立・投資の年度末残高、積立後に使える年間収支を表示"><text x="${L}" y="14" font-size="13" fill="#526d7a">年度末資産</text><text x="${W-R}" y="14" text-anchor="end" font-size="13" fill="#a45d26">年間収支</text>${ticks}${bars}<polyline points="${line}" fill="none" stroke="#dc8139" stroke-width="3" vector-effect="non-scaling-stroke"/>${rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.net,net)}" r="${r.net<0?5:3}" fill="${r.net<0?'#c33b32':'#dc8139'}"/><rect data-chart-year="${r.year}" x="${x(i)-(mobile?barArea/rows.length/2:Math.max(8,barArea/rows.length/2))}" y="${T}" width="${mobile?barArea/rows.length:Math.max(16,barArea/rows.length)}" height="${plot}" fill="transparent" tabindex="0" aria-label="${r.year}年度の資産と収支を見る"/>`).join('')}${rows.map((r,i)=>i===0||i===rows.length-1||i%step===0?`<text x="${x(i)}" y="${H-12}" text-anchor="middle" font-size="12" fill="#526d7a">${r.year}</text>`:'').join('')}</svg></div><div class="chart-tooltip-slot"><div class="chart-tooltip" role="status" hidden></div></div></div>`
}
